add_shortcode( 'trending_products', 'perfectpixel_trending_products_shortcode' );

function perfectpixel_trending_products_shortcode( $atts ) {
	global $wpdb;
	$atts  = shortcode_atts( array( 'days' => 7, 'limit' => 4, 'columns' => 4 ), $atts );
	$days  = min( 365, max( 1, absint( $atts['days'] ) ) );
	$limit = min( 24, max( 1, absint( $atts['limit'] ) ) );
	$key   = 'perfectpixel_trending_' . $days . '_' . $limit;
	$ids   = get_transient( $key );
	if ( false === $ids ) {
		$ids = $wpdb->get_col(
			$wpdb->prepare(
				"SELECT l.product_id FROM {$wpdb->prefix}wc_order_product_lookup l
				INNER JOIN {$wpdb->prefix}wc_order_stats s ON s.order_id = l.order_id
				INNER JOIN {$wpdb->posts} p ON p.ID = l.product_id AND p.post_status = 'publish'
				WHERE l.date_created >= %s AND s.status IN ('wc-completed','wc-processing')
				GROUP BY l.product_id ORDER BY SUM(l.product_qty) DESC LIMIT %d",
				gmdate( 'Y-m-d H:i:s', time() - $days * DAY_IN_SECONDS ),
				$limit
			)
		);
		$ids = array_map( 'intval', (array) $ids );
		set_transient( $key, $ids, HOUR_IN_SECONDS );
	}
	if ( ! $ids ) {
		return '';
	}
	return do_shortcode( sprintf( '[products ids="%s" columns="%d" orderby="post__in"]', esc_attr( implode( ',', $ids ) ), min( 6, max( 1, absint( $atts['columns'] ) ) ) ) );
}
